local users = {token_a = "alice", token_b = "bob"}
local documents = {a = {owner = "alice", body = "alice-private"}, b = {owner = "bob", body = "bob-private"}}
local function read_document(actor, id)
  local document = documents[id]
  if not document then return 404, "missing" end
  if document.owner ~= actor then return 403, "forbidden" end
  return 200, document.body
end
function handle(request)
  local actor = users[request.headers.authorization]
  if not actor then return 401, "login" end
  if request.method ~= "GET" or request.path ~= "/documents" then return 404, "route" end
  return read_document(actor, request.query.id)
end
return {handle = handle}

